using System;using System.Collections.Generic;using System.Linq;using System.Reflection;using System.Text.Json;using Deception.Core;using Deception.PolyModAdapter;using Polytopia.Data;
namespace Deception.Tests
{
 public static class EmbassyUiTests
 {
  static int Assertions;static List<string> Cases=new();static void Check(bool b,string why){Assertions++;if(!b)throw new Exception(why);}
  static void Test(string name,Action body){try{typeof(UiAdapterTests).GetMethod("Reset",BindingFlags.Static|BindingFlags.NonPublic)!.Invoke(null,null);NativeBlackmailEmbassyUi.Clear();NativeRegroupSession.Enabled=true;NativeBlackmail.Reset();HotSeatOverlay.IsActive=false;TileDataExtensions.NativeEmbassyIncome=0;body();Check(!Entry.Notes.Any(n=>n.Kind=="blackmail-embassy-ui-error"),"unexpected UI error: "+string.Join(";",Entry.Notes.Where(n=>n.Kind=="blackmail-embassy-ui-error").Select(n=>n.Message)));Cases.Add(name);}catch(Exception e){throw new Exception(name,e);}}
  sealed class Scene
  {
   internal readonly GameState State=GameManager.GameState;internal readonly MapRenderer Map=new();internal readonly TileData Data;internal readonly Tile Tile;internal readonly City City;internal readonly CityStatusNameContainer Label=new();
   internal Scene(){GameManager.LocalPlayer.Id=1;State.Players[1]=GameManager.LocalPlayer;State.Players[2]=new(){Id=2};State.Players[3]=new(){Id=3};MapRenderer.Current=Map;Data=new(){coordinates=new(2,3),owner=2,Improvement=ImprovementData.Type.city};State.Map.Add(Data);Tile=new(){Data=Data,Coordinates=Data.coordinates};Map.Tiles[(2,3)]=Tile;City=new(){Tile=Tile,Owner=State.Players[2]};Tile.Improvement=City;NativeBlackmail.Set(new LedgerBlackmail(1,2,2,3,State.CurrentTurn));}
   internal int Native()=>TileDataExtensions.CalculateWork(Data,State,GameManager.LocalPlayer,1);internal void Draw()=>Label.SetCity(City);
   internal NativeBlackmailEmbassyUi.Scope Scope(){NativeBlackmailEmbassyUi.BeforeCity(Label,City,out var scope);Label.city=City;return scope;}
  }
  public static int Run(){try{
   Test("EMBASSY-UI-001-native-star-label-shows-blackmail",()=>{var s=new Scene();s.Draw();Check(s.Label.Text=="1"&&s.Label.workContainer.gameObject.activeSelf,"native zero→one under-city star label");Check(s.Native()==0,"outside display scope native economy untouched");});
   Test("EMBASSY-UI-016-stacked-layers-use-native-income",()=>{var s=new Scene();NativeBlackmail.Set(new LedgerBlackmail(1,2,2,3,1){Layers=3},new LedgerBlackmail(3,2,2,3,1){Layers=2});s.Draw();Check(s.Label.Text=="3","own incoming layers, not number of unit contracts");GameManager.LocalPlayer=s.State.Players[3];s.Draw();Check(s.Label.Text=="2","other actor sees their distinct layer total");});
   Test("EMBASSY-UI-017-gross-capacity-query-is-fenced",()=>{var s=new Scene();NativeBlackmail.ReadingGrossIncome=true;s.Draw();Check(s.Label.Text=="0","gross capacity must not borrow foreign income projection");NativeBlackmail.ReadingGrossIncome=false;});
   Test("EMBASSY-UI-002-existing-embassy-combines",()=>{var s=new Scene();TileDataExtensions.NativeEmbassyIncome=2;s.Draw();Check(s.Label.Text=="3","native embassy2 plus blackmail1");Check(s.Native()==2,"native embassy mechanics unchanged");});
   Test("EMBASSY-UI-003-only-viewers-own-income",()=>{var s=new Scene();NativeBlackmail.Set(new LedgerBlackmail(1,2,2,3,1),new LedgerBlackmail(3,2,2,3,1));s.Draw();Check(s.Label.Text=="1","other blackmailer excluded");GameManager.LocalPlayer=s.State.Players[3];s.Draw();Check(s.Label.Text=="1","hotseat viewer sees own mark");});
   Test("EMBASSY-UI-004-victim-city-native-net-branch-preserved",()=>{var s=new Scene();GameManager.LocalPlayer=s.State.Players[2];s.Draw();Check(s.Label.Text=="5","foreign-only adapter leaves victim producer unchanged");});
   Test("EMBASSY-UI-005-no-mark-native-zero-remains-hidden",()=>{var s=new Scene();NativeBlackmail.Set();s.Draw();Check(s.Label.Text=="0"&&!s.Label.workContainer.gameObject.activeSelf,"no unsolicited income label");});
   Test("EMBASSY-UI-006-native-riot-or-private-omission-retained",()=>{var s=new Scene();s.Label.OmitWork=true;s.Draw();Check(s.Label.Text==""&&!s.Label.workContainer.gameObject.activeSelf,"do not force omitted native work label");});
   foreach(string guard in new[]{"hidden","unexplored","inactive-tile","inactive-map","inactive-city","inactive-label","detached-tile","detached-data","detached-city","wrong-owner","capture","no-city","replay","spectator","hotseat","client-state","unready","disabled"})Test("EMBASSY-UI-007-context-"+guard,()=>{var s=new Scene();switch(guard){case"hidden":s.Tile.IsHidden=true;break;case"unexplored":s.Data.Explored=false;break;case"inactive-tile":s.Tile.gameObject.SetActive(false);break;case"inactive-map":s.Map.gameObject.SetActive(false);break;case"inactive-city":s.City.gameObject.SetActive(false);break;case"inactive-label":s.Label.gameObject.SetActive(false);break;case"detached-tile":s.Map.Tiles[(2,3)]=new(){Data=s.Data};break;case"detached-data":s.State.Map.Tiles[(2,3)]=new(){coordinates=s.Data.coordinates};break;case"detached-city":s.Tile.Improvement=new City();break;case"wrong-owner":s.City.Owner=s.State.Players[3];break;case"capture":s.Data.owner=3;break;case"no-city":s.Data.Improvement=null;break;case"replay":GameManager.Client.IsReplay=true;break;case"spectator":GameManager.Client.IsSpectating=true;break;case"hotseat":HotSeatOverlay.IsActive=true;break;case"client-state":GameManager.Client.GameState=new();break;case"unready":GameManager.Client.IsReady=false;break;case"disabled":NativeRegroupSession.Enabled=false;break;}s.Draw();Check(s.Label.Text=="0","invalid city/view must not reveal income");});
   foreach(string guard in new[]{"turn","snapshot","viewer","city-pool","fog","clear"})Test("EMBASSY-UI-008-mid-query-"+guard,()=>{var s=new Scene();var scope=s.Scope();switch(guard){case"turn":s.State.CurrentTurn++;break;case"snapshot":NativeGameStateEnvelope.Invalidate();break;case"viewer":GameManager.LocalPlayer=s.State.Players[3];break;case"city-pool":s.Label.city=new();break;case"fog":s.Tile.IsHidden=true;break;case"clear":NativeBlackmailEmbassyUi.Clear();break;}Check(s.Native()==0,"stale scope fenced");NativeBlackmailEmbassyUi.Finished(null,scope);});
   Test("EMBASSY-UI-009-native-refresh-clears-removed-row",()=>{var s=new Scene();s.Draw();NativeBlackmail.Set();s.Draw();Check(s.Label.Text=="0"&&!s.Label.workContainer.gameObject.activeSelf,"native pool refresh removes stale income");});
   Test("EMBASSY-UI-010-nested-invalid-scope-and-finalizer",()=>{var s=new Scene();var outer=s.Scope();Check(s.Native()==1,"outer scope valid");NativeBlackmailEmbassyUi.BeforeCity(new CityStatusNameContainer(),new City(),out var inner);Check(s.Native()==0,"invalid inner fences outer");NativeBlackmailEmbassyUi.Finished(null,inner);Check(s.Native()==1,"outer resumes");var error=new Exception("native");Check(ReferenceEquals(error,NativeBlackmailEmbassyUi.Finished(error,outer))&&s.Native()==0,"exception preserved and cleanup");NativeBlackmailEmbassyUi.Finished(null,outer);Check(s.Native()==0,"duplicate completion inert");});
   Test("EMBASSY-UI-011-no-authoritative-mutation",()=>{var s=new Scene();var snap=NativeGameStateEnvelope.Get(s.State);var money=GameManager.LocalPlayer.Currency;for(int i=0;i<30;i++)s.Draw();Check(ReferenceEquals(snap,NativeGameStateEnvelope.Get(s.State))&&GameManager.LocalPlayer.Currency==money&&s.Data.owner==2,"display never alters state/ledger/treasury");});
   Test("EMBASSY-UI-012-unrelated-query-and-skipped-native",()=>{var s=new Scene();var scope=s.Scope();int v=4;NativeBlackmailEmbassyUi.Income(s.Data,s.State,GameManager.LocalPlayer,false,ref v);Check(v==4,"skipped native untouched");NativeBlackmailEmbassyUi.Income(s.Data,s.State,s.State.Players[2],true,ref v);Check(v==4,"owner query cannot borrow viewer scope");NativeBlackmailEmbassyUi.Income(new TileData(),s.State,GameManager.LocalPlayer,true,ref v);Check(v==4,"other city untouched");NativeBlackmailEmbassyUi.Finished(null,scope);});
   Console.WriteLine(JsonSerializer.Serialize(new{passed=true,cases=Cases.Count,assertions=Assertions,tests=Cases,scope="Production city income scope with native-shaped UI ports; no gameplay"}));return 0;
  }catch(Exception e){Console.WriteLine(JsonSerializer.Serialize(new{passed=false,cases=Cases.Count,assertions=Assertions,error=e.ToString()}));return 1;}}
 }
}
